import { describe, it, expect } from "vitest";
import { render } from "@testing-library/react";
import App from "./App";

describe("App", () => {
  it("renders the product heading", () => {
    const { getByRole } = render(<App />);
    expect(getByRole("heading", { level: 1 }).textContent).toBe("{{app_name}}");
  });
});
